/// Minimal Monarch tokenizer for TOML (package manifests) — Monaco ships
/// `ini` but no `toml`. Covers comments, basic/literal strings (single and
/// multiline), booleans, dates/times, numbers (incl. hex/oct/bin/inf/nan),
/// bare keys, and table headers.
fn toml_monarch_json() -> serde_json::Value {
    serde_json::json!({
        "defaultToken": "",
        "brackets": [
            { "open": "[", "close": "]", "token": "delimiter.square" },
            { "open": "{", "close": "}", "token": "delimiter.curly" }
        ],
        "tokenizer": {
            "root": [
                ["#.*$", "comment"],
                ["\\[\\[[^\\]\\n]+\\]\\]", "type.identifier"],
                ["\\[[^\\]\\n]+\\]", "type.identifier"],
                ["\"\"\"", "string.quote", "@string_ml_double"],
                ["'''", "string.quote", "@string_ml_single"],
                ["\"", "string.quote", "@string_double"],
                ["'", "string.quote", "@string_single"],
                ["\\b(true|false)\\b", "keyword"],
                ["\\b\\d{4}-\\d{2}-\\d{2}([Tt ][0-9:.]+([Zz]|[+-]\\d{2}:?\\d{2})?)?\\b", "number"],
                ["\\b\\d{2}:\\d{2}:\\d{2}(\\.\\d+)?\\b", "number"],
                ["[+-]?(0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+|[0-9][0-9_]*(\\.[0-9_]+)?([eE][+-]?[0-9]+)?|inf|nan)\\b", "number"],
                ["[A-Za-z0-9_-]+(?=\\s*=)", "identifier"],
                ["[=,.]", "operator"],
                ["[\\[\\]{}]", "@brackets"],
                ["\\s+", "white"]
            ],
            "string_double": [
                ["\\\\.", "string.escape"],
                ["\"", "string.quote", "@pop"],
                ["[^\\\\\"\\n]+", "string"]
            ],
            "string_single": [
                ["'", "string.quote", "@pop"],
                ["[^'\\n]+", "string"]
            ],
            "string_ml_double": [
                ["\\\\.", "string.escape"],
                ["\"\"\"", "string.quote", "@pop"],
                ["[^\\\\\"]+", "string"],
                ["\"", "string"]
            ],
            "string_ml_single": [
                ["'''", "string.quote", "@pop"],
                ["[^']+", "string"],
                ["'", "string"]
            ]
        }
    })
}

fn toml_monarch() -> JsValue {
    json_to_js(&toml_monarch_json())
}

fn toml_language_configuration_json() -> serde_json::Value {
    serde_json::json!({
        "comments": { "lineComment": "#" },
        "brackets": [["[", "]"], ["{", "}"]],
        "autoClosingPairs": [
            { "open": "[", "close": "]" },
            { "open": "{", "close": "}" },
            { "open": "\"", "close": "\"", "notIn": ["string", "comment"] },
            { "open": "'", "close": "'", "notIn": ["string", "comment"] }
        ],
        "surroundingPairs": [
            { "open": "[", "close": "]" },
            { "open": "{", "close": "}" },
            { "open": "\"", "close": "\"" },
            { "open": "'", "close": "'" }
        ]
    })
}

fn toml_language_configuration() -> JsValue {
    json_to_js(&toml_language_configuration_json())
}

/// Monarch tokenizer for Nix expressions and NixOS modules.
///
/// Token classes: `comment` (`#` line and `/* */` block), `keyword`
/// (`assert else if in inherit let or rec then with` plus the `true` /
/// `false` / `null` constants), `string` and `string.quote` for `"…"` and
/// `''…''` (with `string.escape` for `\` / `''$` / `'''` escapes and for
/// the `${ … }` delimiters, whose interior is tokenized as an expression),
/// `type.identifier` for attribute names in binding position, `number`,
/// `operator`, and `delimiter.*` via `@brackets`. Path (`./x`, `~/x`,
/// `<nixpkgs>`) and URI literals are `string`.
fn nix_monarch_json() -> serde_json::Value {
    serde_json::json!({
        "defaultToken": "",
        "keywords": [
            "assert", "else", "if", "in", "inherit", "let", "or", "rec",
            "then", "with", "true", "false", "null"
        ],
        "brackets": [
            { "open": "{", "close": "}", "token": "delimiter.curly" },
            { "open": "[", "close": "]", "token": "delimiter.square" },
            { "open": "(", "close": ")", "token": "delimiter.parenthesis" }
        ],
        "tokenizer": {
            "root": [
                ["#.*$", "comment"],
                ["/\\*", "comment", "@block_comment"],
                ["''", "string.quote", "@string_indented"],
                ["\"", "string.quote", "@string_double"],
                ["[a-zA-Z][a-zA-Z0-9+.-]*://[^\\s;,)\\]}]+", "string"],
                ["(?:\\.{0,2}/|~/|<)[^\\s;,)\\]}]*", "string"],
                ["\\b\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?\\b", "number"],
                ["[a-zA-Z_][a-zA-Z0-9_'-]*(?=\\s*=[^=])", "type.identifier"],
                {
                    "regex": "[a-zA-Z_][a-zA-Z0-9_'-]*",
                    "action": { "cases": { "@keywords": "keyword", "@default": "identifier" } }
                },
                ["\\|\\||&&|==|!=|<=|>=|->|//|\\+\\+|\\*\\*", "operator"],
                ["[+\\-*/<>!=&|@:?.,;\\\\]", "operator"],
                ["[{}()\\[\\]]", "@brackets"]
            ],
            "block_comment": [
                ["\\*/", "comment", "@pop"],
                ["[^*]+", "comment"],
                ["\\*", "comment"]
            ],
            "string_double": [
                ["\\\\[\\s\\S]", "string.escape"],
                ["\\$\\{", "string.escape", "@interp"],
                ["\"", "string.quote", "@pop"],
                ["[^\\\\\"$]+", "string"],
                ["\\$", "string"]
            ],
            "string_indented": [
                ["'''", "string.escape"],
                ["''\\$", "string.escape"],
                ["\\$\\{", "string.escape", "@interp"],
                ["''", "string.quote", "@pop"],
                ["[^'$]+", "string"],
                ["'", "string"],
                ["\\$", "string"]
            ],
            "interp": [
                ["\\}", "string.escape", "@pop"],
                ["\\{", "delimiter.curly", "@brace"],
                { "include": "@root" }
            ],
            "brace": [
                ["\\}", "delimiter.curly", "@pop"],
                ["\\{", "delimiter.curly", "@brace"],
                { "include": "@root" }
            ]
        }
    })
}

fn nix_monarch() -> JsValue {
    json_to_js(&nix_monarch_json())
}

fn nix_language_configuration_json() -> serde_json::Value {
    serde_json::json!({
        "comments": { "lineComment": "#", "blockComment": ["/*", "*/"] },
        "brackets": [["{", "}"], ["[", "]"], ["(", ")"]],
        "wordPattern": "[a-zA-Z_][a-zA-Z0-9_'-]*",
        "autoClosingPairs": [
            { "open": "{", "close": "}" },
            { "open": "[", "close": "]" },
            { "open": "(", "close": ")" },
            { "open": "\"", "close": "\"", "notIn": ["string", "comment"] }
        ],
        "surroundingPairs": [
            { "open": "{", "close": "}" },
            { "open": "[", "close": "]" },
            { "open": "(", "close": ")" },
            { "open": "\"", "close": "\"" }
        ],
        "indentationRules": {
            "increaseIndentPattern": ".*(\\{[^}\"']*|\\([^)\"']*|\\[[^\\]\"']*|=\\s*|\\bthen\\s*|\\belse\\s*)$",
            "decreaseIndentPattern": "^\\s*[)}\\]]"
        }
    })
}

fn nix_language_configuration() -> JsValue {
    json_to_js(&nix_language_configuration_json())
}

/// Token names the loader's `panel-kit-dark` theme reads (see
/// `panelKitTheme` in `panel-kit-loader.js`). The theme cannot reference CSS
/// custom properties, so the loader asks Rust for each value by these short
/// names; a canonical token that loses one of them fails
/// [`theme_tokens_cover_the_loader_contract`] instead of silently breaking the
/// editor at load time.
#[cfg(test)]
const THEME_TOKEN_KEYS: &[&str] = &[
    "background",
    "border",
    "divider",
    "error",
    "highlight",
    "info",
    "inverse-background",
    "inverse-text",
    "success",
    "surface",
    "tertiary",
    "text",
    "text-muted",
];

/// Build the token map consumed by the loader's `panel-kit-dark` theme.
///
/// Monaco theme data cannot reference CSS custom properties, so Rust passes
/// the canonical values rather than duplicating the palette in JavaScript.
/// Canonical token names carry the CSS custom-property prefix
/// (`color-surface`); the loader indexes them without it.
fn panel_kit_theme_map() -> Vec<(&'static str, &'static str)> {
    tokens::DARK
        .iter()
        .map(|token| {
            (
                token.name.strip_prefix("color-").unwrap_or(token.name),
                token.hex,
            )
        })
        .collect()
}

fn panel_kit_theme_tokens() -> JsValue {
    let values = js_sys::Object::new();
    for (name, hex) in panel_kit_theme_map() {
        let _ = js_sys::Reflect::set(
            values.as_ref(),
            &JsValue::from_str(name),
            &JsValue::from_str(hex),
        );
    }
    values.into()
}

/// The Monarch grammars are data, so they are checked against the same rules
/// Monaco applies: rules within a state are tried in order at the current
/// offset, `@state` pushes, `@pop` returns, and unmatched text takes
/// `defaultToken`. `tokenize` is a reduced implementation of that contract —
/// enough to prove a sample highlights the way the grammar claims, which is
/// the only observable the browser exercises and no SSR test can reach.
#[cfg(test)]
mod monarch_tests {
    use super::{
        nix_language_configuration_json, nix_monarch_json, pest_monarch_json, toml_monarch_json,
    };
    use serde_json::Value;

    /// (token class, matched text). Empty token classes are omitted.
    ///
    /// Monaco tokenizes one line at a time, so `$` anchors at the end of a
    /// line and no rule spans a newline; state persists across lines.
    fn tokenize(grammar: &Value, text: &str) -> Vec<(String, String)> {
        let mut stack: Vec<String> = vec!["root".to_string()];
        let mut out: Vec<(String, String)> = Vec::new();
        for line in text.split_inclusive('\n') {
            tokenize_line(
                grammar,
                line.strip_suffix('\n').unwrap_or(line),
                &mut stack,
                &mut out,
            );
        }
        out
    }

    fn tokenize_line(
        grammar: &Value,
        text: &str,
        stack: &mut Vec<String>,
        out: &mut Vec<(String, String)>,
    ) {
        let default_token = grammar["defaultToken"].as_str().unwrap_or("");
        let brackets = grammar["brackets"].as_array().cloned().unwrap_or_default();
        let keywords = grammar["keywords"].as_array().cloned().unwrap_or_default();
        let mut offset = 0usize;

        while offset < text.len() {
            let state = stack.last().expect("state stack never empties").clone();
            let rules = rules_for(grammar, &state);
            let mut consumed = None;
            for rule in &rules {
                let include = rule
                    .as_object()
                    .and_then(|object| object.get("include"))
                    .and_then(Value::as_str);
                if let Some(include) = include {
                    let included = rules_for(grammar, include.trim_start_matches('@'));
                    for inner in included {
                        if let Some(hit) =
                            apply(&inner, &text[offset..], stack, &keywords, &brackets, &state)
                        {
                            consumed = Some(hit);
                            break;
                        }
                    }
                    if consumed.is_some() {
                        break;
                    }
                    continue;
                }
                if let Some(hit) = apply(rule, &text[offset..], stack, &keywords, &brackets, &state)
                {
                    consumed = Some(hit);
                    break;
                }
            }
            let (length, token) = consumed.unwrap_or_else(|| {
                // Unmatched: Monaco advances one character as defaultToken.
                let end = text[offset..].chars().next().map_or(1, char::len_utf8);
                (end, default_token.to_string())
            });
            if !token.is_empty() {
                out.push((token, text[offset..offset + length].to_string()));
            }
            offset += length;
        }
    }

    fn rules_for(grammar: &Value, state: &str) -> Vec<Value> {
        grammar["tokenizer"][state]
            .as_array()
            .unwrap_or_else(|| panic!("monarch state `{state}` does not exist"))
            .clone()
    }

    fn apply(
        rule: &Value,
        rest: &str,
        stack: &mut Vec<String>,
        keywords: &[Value],
        brackets: &[Value],
        state: &str,
    ) -> Option<(usize, String)> {
        let (pattern, token, next) = match rule {
            Value::Array(items) => (
                items[0].as_str().expect("regex is a string"),
                items.get(1).and_then(Value::as_str),
                items.get(2).and_then(Value::as_str),
            ),
            Value::Object(object) => (
                object["regex"].as_str().expect("regex is a string"),
                None,
                None,
            ),
            _ => panic!("malformed rule in `{state}`"),
        };
        let regex =
            fancy_regex::Regex::new(&format!("^(?:{pattern})")).expect("monarch regex compiles");
        let matched = regex.find(rest).ok().flatten()?;
        if matched.start() != 0 || matched.end() == 0 {
            return None;
        }
        let text = &rest[..matched.end()];
        let class = match (token, &rule["action"]) {
            (Some(token), _) => token.to_string(),
            (None, Value::Object(action)) => {
                if let Some(next) = action.get("next").and_then(Value::as_str) {
                    transition(next, stack);
                }
                match action.get("token").and_then(Value::as_str) {
                    Some(token) => token.to_string(),
                    None => match &action["cases"] {
                        Value::Object(cases) => {
                            let hit = if keywords.iter().any(|k| k.as_str() == Some(text)) {
                                cases.get("@keywords")
                            } else {
                                cases.get("@default")
                            };
                            hit.and_then(Value::as_str).unwrap_or_default().to_string()
                        }
                        _ => String::new(),
                    },
                }
            }
            _ => String::new(),
        };
        if let Some(next) = next {
            transition(next, stack);
        }
        let class = if class == "@brackets" {
            brackets
                .iter()
                .find(|entry| {
                    entry["open"].as_str() == Some(text) || entry["close"].as_str() == Some(text)
                })
                .and_then(|entry| entry["token"].as_str())
                .unwrap_or("delimiter")
                .to_string()
        } else {
            class
        };
        Some((matched.end(), class))
    }

    fn transition(next: &str, stack: &mut Vec<String>) {
        match next {
            "@pop" => {
                assert!(stack.len() > 1, "pop below the root state");
                stack.pop();
            }
            _ => stack.push(next.trim_start_matches('@').to_string()),
        }
    }

    /// Every `@state` a grammar names must be defined, or highlighting stops
    /// at the first mention of the missing state and tokens after it are
    /// silently wrong.
    fn assert_states_defined(grammar: &Value) {
        let states: Vec<String> = grammar["tokenizer"]
            .as_object()
            .expect("tokenizer is an object")
            .keys()
            .cloned()
            .collect();
        for (state, rules) in grammar["tokenizer"].as_object().unwrap() {
            for rule in rules.as_array().unwrap() {
                let mut referenced = Vec::new();
                match rule {
                    Value::Array(items) => {
                        if let Some(next) = items.get(2).and_then(Value::as_str) {
                            referenced.push(next.to_string());
                        }
                    }
                    Value::Object(object) => {
                        if let Some(include) = object.get("include").and_then(Value::as_str) {
                            referenced.push(include.to_string());
                        }
                        if let Some(next) = object
                            .get("action")
                            .and_then(|a| a.get("next"))
                            .and_then(Value::as_str)
                        {
                            referenced.push(next.to_string());
                        }
                    }
                    _ => panic!("malformed rule in `{state}`"),
                }
                for reference in referenced {
                    if reference == "@pop" {
                        continue;
                    }
                    let name = reference.trim_start_matches('@');
                    assert!(
                        states.iter().any(|s| s == name),
                        "state `{state}` references undefined state `{reference}`"
                    );
                }
            }
        }
    }

    #[test]
    fn every_grammar_references_defined_states() {
        for grammar in [nix_monarch_json(), pest_monarch_json(), toml_monarch_json()] {
            assert_states_defined(&grammar);
        }
    }

    #[test]
    fn nix_keywords_and_bindings_highlight() {
        let tokens = tokenize(&nix_monarch_json(), "let x = 1; in x");
        let classes: Vec<&str> = tokens.iter().map(|(token, _)| token.as_str()).collect();
        assert_eq!(
            tokens,
            vec![
                ("keyword".to_string(), "let".to_string()),
                // Binding names (`let x = …`, `attr = …`) share one class:
                // Monarch has no state that distinguishes let from an attrset.
                ("type.identifier".to_string(), "x".to_string()),
                ("operator".to_string(), "=".to_string()),
                ("number".to_string(), "1".to_string()),
                ("operator".to_string(), ";".to_string()),
                ("keyword".to_string(), "in".to_string()),
                ("identifier".to_string(), "x".to_string()),
            ],
            "got {classes:?}"
        );
    }

    #[test]
    fn nix_attribute_names_are_attributes_not_identifiers() {
        let tokens = tokenize(&nix_monarch_json(), "{ services.nginx.enable = true; }");
        assert!(
            tokens.contains(&("type.identifier".to_string(), "enable".to_string())),
            "binding key must be an attribute: {tokens:?}"
        );
        assert!(
            tokens.contains(&("keyword".to_string(), "true".to_string())),
            "constants are keywords: {tokens:?}"
        );
    }

    #[test]
    fn nix_string_interpolation_reenters_expressions() {
        let tokens = tokenize(&nix_monarch_json(), "\"a ${name} b\"");
        assert_eq!(
            tokens,
            vec![
                ("string.quote".to_string(), "\"".to_string()),
                ("string".to_string(), "a ".to_string()),
                ("string.escape".to_string(), "${".to_string()),
                ("identifier".to_string(), "name".to_string()),
                ("string.escape".to_string(), "}".to_string()),
                ("string".to_string(), " b".to_string()),
                ("string.quote".to_string(), "\"".to_string()),
            ]
        );
    }

    #[test]
    fn nix_indented_strings_and_comments_close_their_states() {
        let tokens = tokenize(
            &nix_monarch_json(),
            "''\n  a ${x}\n''\n# trailing\n/* block */",
        );
        assert_eq!(
            tokens.first(),
            Some(&("string.quote".to_string(), "''".to_string()))
        );
        assert!(tokens.contains(&("string.escape".to_string(), "${".to_string())));
        assert!(
            tokens.contains(&("comment".to_string(), "# trailing".to_string())),
            "{tokens:?}"
        );
        assert!(tokens.contains(&("comment".to_string(), "/*".to_string())));
        assert!(tokens.contains(&("comment".to_string(), "*/".to_string())));
        let quotes = tokens
            .iter()
            .filter(|(token, _)| token == "string.quote")
            .count();
        assert_eq!(
            quotes, 2,
            "the indented string opens and closes: {tokens:?}"
        );
    }

    #[test]
    fn nix_paths_are_literals_not_operators() {
        let tokens = tokenize(&nix_monarch_json(), "import ./flake.nix");
        assert!(
            tokens.contains(&("string".to_string(), "./flake.nix".to_string())),
            "path literal must be one token: {tokens:?}"
        );
    }

    #[test]
    fn theme_tokens_cover_the_loader_contract() {
        let map: std::collections::BTreeMap<&str, &str> =
            super::panel_kit_theme_map().into_iter().collect();
        for key in super::THEME_TOKEN_KEYS {
            assert!(
                map.contains_key(key),
                "loader reads token `{key}`; canonical tokens provide {:?}",
                map.keys().collect::<Vec<_>>()
            );
        }
    }

    #[test]
    fn nix_configuration_declares_the_language_contract() {
        let config = nix_language_configuration_json();
        assert_eq!(config["comments"]["lineComment"], "#");
        assert_eq!(config["comments"]["blockComment"][0], "/*");
        assert!(config["indentationRules"]["increaseIndentPattern"].is_string());
    }
}
